entries[265778] = { ["name"] = "Hollowcore Harpoon Turret", ["text"] = "Binds when picked up\nUnique\nUse: Tier 3\nUnlocks the Hallowcore Harpoon Turret for use.\n\nSpeak with Depthdiver Jeju to swap your harpoon.\n\nHollowcore Harpoon Turret\n35 yd range 1 sec cast 1 sec cooldown\nShoot a deadly harpoons twice as fast, destroying a layer of Fish Scale and capturing vulnerable fish.\n\nTheir range is shortened due to their lightweight materials." }
entries[265779] = { ["name"] = "Heavy Harpoon Cannon", ["text"] = "Binds when picked up\nUnique\nUse: Tier 3\nUnlocks the Heavy Harpoon Canon for use.\n\nSpeak with Depthdiver Jeju to swap your harpoon.\n\nHeavy Harpoon Cannon\n25 yd range 2 sec cast 1 sec cooldown\nShoot a heavy harpoon at the cost of range.\n\nDestroys 2 layers of Fish Scales, and captures creatures when vulnerable." }
