entries[266100] = { ["name"] = "Barbed Riftwalker Dirk", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Dagger\n1 Damage Speed 1.80\n(0.6 damage per second)\nDurability 20 / 20\n\"Riftwalkers out in the field have to make quick decisions and repurpose enemy armaments in a pinch.\"\nUse: Add this appearance to your Warband collection." }
