entries[266120] = { ["name"] = "Sisterhood's Crescent", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Sword\n1 Damage Speed 2.60\n(0.4 damage per second)\n\"Originally favored by the martially-skilled Sisters of Elune, this weapon became standard within the Kaldorei military.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[266121] = { ["name"] = "Sisterhood's Glaive", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Warglaive\n1 Damage Speed 2.60\n(0.4 damage per second)\n\"Before wielding an Umbra Crescent, a Warden trainee must first master the twin-bladed glaive.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[266122] = { ["name"] = "Archer's Night Sabre", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Sword\n1 Damage Speed 2.60\n(0.4 damage per second)\n\"As the last arrow flies, the archer's blade cuts through shadows like moonlight in the dark.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
