entries[266125] = { ["name"] = "Priestess' Starblade", ["text"] = "Cosmetic\nBinds to Warband\nOne-Hand Dagger\n1 Damage Speed 1.80\n(0.6 damage per second)\n\"While the Sisters of Elune traditionally no longer wield glaive nor lance, many continue to carry starblades as personal armaments.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
