entries[266985] = { ["name"] = "Hearty Silvermoon Parade", ["text"] = "Binds to Warband until equipped\nUse: Place a Hearty Silvermoon Parade\nfor all players to enjoy!\n\nRestores 7% of your maximum health and mana every second over 20 sec. Must remain seated while eating.\n\nHearty Well Fed\nIf you spend at least 10 seconds eating you will become Hearty Well Fed gaining 98 Stamina and 50 primary stat for 1 hour.\n\nThis effect persists through death.\nSell Price:" }
entries[266986] = { ["name"] = "Hearty Quel'dorei Medley", ["text"] = "Binds to Warband until equipped\nUse: Place a Hearty Quel'dorei Medley for all players to enjoy!\n\nRestores 7% of your maximum health and mana every second over 20 sec. Must remain seated while eating.\n\nHearty Well Fed\nIf you spend at least 10 seconds eating you will become Hearty Well Fed gaining 98 Stamina and 65 of your highest secondary stat for 1 hour.\n\nThis aura persists through death.\nSell Price:" }
