entries[268552] = { ["name"] = "Ascendant Voidcore", ["text"] = "Midnight Season 1\nBinds when picked up\nUse: Increase the item level of a fully upgraded Hero or Myth or maximum quality Radiance Crafted weapon or trinket from Midnight Season 1.\n\"Weave the Voidcore's energy into worthy equipment with Decimus's assistance at the Howling Ridge in the Voidstorm.\"\nSell Price:" }
entries[268557] = { ["name"] = "Akiki", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to summon this companion.\n\nRight Click to summon and dismiss Nar'loka.\nRequires level 1 to 90 ( 90)\nSell Price:" }
entries[268578] = { ["name"] = "Void-Touched Hawkstrider", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires Renown Rank 8 with Ritual Sites.\nSell Price:\n\"Almost no beasts are immune to the void's touch. A few of our scouts' hawkstriders have been affected by the void. I have been observing them now for a bit and they are still fit for service. In some ways they are even more fit for the kind of work you are up to. - Sergeant Vornin\"\nVendor:\nSergeant Vornin\nZone:\nSilvermoon City\nRenown:\nRitual Sites Rank 8\nCost:\n4500" }
entries[268584] = { ["name"] = "Undamaged Serpent Scale", ["text"] = "Quest Item\n\"Do not hold too long. The toxin is quite potent.\"" }
