entries[268650] = { ["name"] = "Ascendant Voidshard", ["text"] = "Midnight Season 1\nBinds when picked up\nUse: Combine five Ascendant Voidshards into an Ascendant Voidcore.\n\nAt the Voidforge in Howling Ridge, Voidcores are capable of increasing the item level of a fully upgraded Hero or Myth or maximum quality Radiance Crafted weapon or trinket from Midnight Season 1.\n\"Although only a fragment of a Voidcore, it hums with an unnerving power. More may be found by defeating powerful foes.\"\nSell Price:" }
entries[268679] = { ["name"] = "Hearty Impossibly Royal Roast", ["text"] = "Vegetarian\nBinds to Warband until equipped\nUse: Restores 7% of your maximum health and mana every second over 20 sec. Must remain seated while eating.\n\nHearty Well Fed\nIf you spend at least 10 seconds eating you will become Hearty Well Fed and gain 50 primary stat for 1 hour.\n\nThis food persists through death.\nSell Price:" }
