entries[268833] = { ["name"] = "Zothwing Darkseeker", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Do not let its cloying looks fool you--zothwing darkseekers are a remnant of an ancient Black Empire species. Pay no attention to whispers mentioning \"snackies\" for your \"trusty mount.\"\"\nIn-Game Shop" }
entries[268834] = { ["name"] = "Zothwing Deepseeker", ["text"] = "Binds to Warband\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"A gift of N'Zoth, Zothwing Deepseekers are as at home in the crushing depths of Azeroth's oceans as they are in the bitter cold of the void.\"\nIn-Game Shop" }
entries[268871] = { ["name"] = "Specifically Sized Rock", ["text"] = "Quest Item\n\"Seems to be roughly the right shape. If you squint.\"" }
entries[268876] = { ["name"] = "Flame-Painted Sun Roc", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"In ages past, the sun rocs of Kalimdor were believed to be the messengers of An'she, carrying with them the first flame before dawn and the final light of evenfall.\"\nTrading Post" }
entries[268877] = { ["name"] = "Dusk-Painted Sun Roc", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"Long ago, the dusk-painted silhouettes of these sun rocs inspired many fireside myths. Their return to Kalimdor has reignited lost stories of these heralds of An'she.\"\nTrading Post" }
