entries[268944] = { ["name"] = "Souvenir Halazzi Idol", ["text"] = "Unique\n\"A cheaply-made, mass-produced, but surprisingly accurate scale model of a Halazzi shrine idol made for tourists.\"" }
entries[268945] = { ["name"] = "Souvenir Nalorakk Mask", ["text"] = "Unique\n\"A papier mache scale model of Nalorakk's stone mask. Sadly, it is glued to a stand.\"" }
entries[268946] = { ["name"] = "Souvenir Jan'alai Key Chain", ["text"] = "Unique\n\"A resin model of a Jan'alai mask in minature on a chain meant to keep keys together and tidy. It's a bit gauche.\"" }
entries[268947] = { ["name"] = "Souvenir Akil'zon Shine Paper Weight", ["text"] = "Unique\n\"A small model Akil'zon shrine under clear resin to commemorate your travels to Zul'Aman--if you survive.\"" }
entries[268948] = { ["name"] = "Fine Antique Silvermoon Drapes", ["text"] = "Unique\n\"Exquisite fabric with very fine stitching.Too bad they are very out of fashion.\"" }
entries[268949] = { ["name"] = "Single Earthen Salt Shaker", ["text"] = "Unique\n\"Being sold solo because 'the earthen don't use pepper.' The veracity of this is questionable.\"" }
entries[268950] = { ["name"] = "Murloc Deterrent", ["text"] = "Quest Item\nUnique\n\"Though the stench is contained, you can tell it is seeping into your skin.\"" }
entries[268951] = { ["name"] = "Familiar Threshadon Tooth Necklace", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires level 90 to 90 ( 90)\n\"This necklace feels familiar... like you are looking at your own handiwork.\"" }
