entries[268954] = { ["name"] = "Entropic Extract", ["text"] = "Use: Opens your mind to the touch of the Void. This effect enhances your appearance for 10 sec to 20 sec but has no bearing on your combat abilities.\n\"Created by experienced alchemists. Can be bought and sold on the Auction House.\"\nSell Price:" }
