entries[268969] = { ["name"] = "Nebulous Voidcache: Delver's Trove", ["text"] = "Binds when picked up\n\"Transmute a Nebulous Voidcore into a piece of equipment for your Loot Specialization. Items may be received once per difficulty level until all potential items have been transmuted.\"\n<Right Click to Open>" }
entries[268970] = { ["name"] = "Majestic Eagle Statue", ["text"] = "Binds when picked up\n\"A powerful eagle in flight. Your local decor vendor has expressed an interest in such things.\"" }
entries[268972] = { ["name"] = "Pressed Sanguithorn", ["text"] = "Binds when picked up\n\"Pressed for preservation. Your local flora decor trader may be interested in this exotic specimen.\"" }
entries[268973] = { ["name"] = "Bone Pen", ["text"] = "Binds when picked up\n\"An Amani pen carved from an animal bone. Your local steward may appreciate it.\"" }
entries[268974] = { ["name"] = "Deactivated Amani Hex Ward", ["text"] = "Binds when picked up\n\"This type of curiosity could be of interest to the Last Architect.\"" }
entries[268975] = { ["name"] = "Amani War Axe", ["text"] = "Binds when picked up\n\"Even while blunted, this axe could be a collector's item for one whose trade involves chopping things.\"" }
entries[268976] = { ["name"] = "\"Aromatic\" Bottle", ["text"] = "Binds when picked up\n\"The foul smelling substance in this bottle should be as far away from your neighborhood as you can get it. You may be able to trade it to people who trade with far off lands.\"" }
entries[268977] = { ["name"] = "Ossein Fish Trinket", ["text"] = "Binds when picked up\n\"Said to bring luck and a bountiful harvest of fish. Could be of use to a person in the fish trade.\"" }
entries[268978] = { ["name"] = "Torga Statue", ["text"] = "Binds when picked up\n\"A very small carving of Torga, the Turtle Loa. If you can find a Tortollan in your neighborhood, they would appreciate this.\"" }
entries[268996] = { ["name"] = "Field Accolade Pouch", ["text"] = "Binds when picked up\nContains 10 Field Accolades.\n\"Maren Silverwing will exchange these for Void-Touched caches in Silvermoon City.\"" }
entries[269001] = { ["name"] = "Arsenal: Drakebreaker's Weapons", ["text"] = "Binds when picked up\nClasses: Warrior , Paladin , Rogue , Death Knight , Shaman , Monk , Demon Hunter , Evoker\nUse: Collect the axe appearance of Drakebreakers from seasons passed." }
entries[269002] = { ["name"] = "Arsenal: Hellbloom Weapons", ["text"] = "Binds when picked up\nClasses: Warrior , Paladin , Rogue , Priest , Death Knight , Shaman , Monk , Druid , Evoker\nUse: Collect the axe appearance of Drakebreakers from seasons passed." }
entries[269005] = { ["name"] = "Preyseeker's Glinting Coin Pouch", ["text"] = "Binds when picked up\n\"A pouch containing 125 gold.\"\n<Right Click to Open>" }
entries[269006] = { ["name"] = "Preyseeker's Gleaming Coin Pouch", ["text"] = "Binds when picked up\n\"A pouch containing 150 gold.\"\n<Right Click to Open>" }
entries[269007] = { ["name"] = "Preyseeker's Glittering Coin Pouch", ["text"] = "Binds when picked up\n\"A pouch containing 175 gold.\"\n<Right Click to Open>" }
entries[269009] = { ["name"] = "Golden Ashened Cataclysm", ["text"] = "Unique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount. This mount changes depending on your riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding" }
entries[269010] = { ["name"] = "Essence of Lumber", ["text"] = "Binds when picked up\n\"A mote of magical energies obtained from harvesting lumber. Used to requisition additional materials from your neighborhood lumberjack.\"" }
entries[269012] = { ["name"] = "Sha-Warped Riding Wolf", ["text"] = "Binds when used\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Sha has warped this wolf into an even more fearsome creature. The emotions that flow through this creature make it an unmistakable harbinger of doom.\"\nPromotion" }
entries[269019] = { ["name"] = "Amani Construction Hammer", ["text"] = "Binds when picked up\n\"A hammer worthy of any builder. It could be a good gift for a contractor.\"" }
entries[269020] = { ["name"] = "Scrimshaw Ward", ["text"] = "Binds when picked up\n\"A grim ward said to scare away evil spirits. Or would, if properly enchanted. As it is, it may be a curiosity to those who peddle in the more macabre decor.\"" }
entries[269021] = { ["name"] = "Jan'alai Bibelot", ["text"] = "Binds when picked up\n\"An artistic rendition of Jan'alai as a sunburst, this is said to ensure that sun always shines and crops will grow. Perhaps a farmer might want it?\"" }
entries[269022] = { ["name"] = "Healing Waters of Ahl'ua", ["text"] = "Quest Item\n\"Tingles to the touch and taste. Intended to counteract the poison of the nearby creatures during Shul'ka rituals.\"" }
entries[269023] = { ["name"] = "Phytogenic Poison Part", ["text"] = "Quest Item\n\"The secretions coming from these plant-like organs are most definitely toxic.\"" }
entries[269028] = { ["name"] = "Sootpaw", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 90 ( 90)" }
entries[269029] = { ["name"] = "Bag of Totally Legitimate Amani Goods", ["text"] = "Binds when picked up\n\"A variety of Amani items, supposedly. These may be of interest to your neighbors.\"\n<Right Click to Open>" }
entries[269234] = { ["name"] = "Overflowing Ritual Site Cache", ["text"] = "Binds to Warband\n\"Contains a variety of rewards for those who have proven themselves adept at facing Ritual Sites.\"\n<Right Click to Open>" }
entries[269240] = { ["name"] = "Luminous Sporeglider", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This sporeglider's voracious appetite for luminescent spores has lent it an exquisite glow.\"\nDrop:\nRotmire\nLocation:\nSporefall" }
entries[269245] = { ["name"] = "Delicious Sporesnack", ["text"] = "Binds to Warband\nUse: Combine four Delicious Sporesnacks to befriend a Luminous Sporeglider.\n\"Not for humanoid consumption.\"\nSell Price:" }
entries[269258] = { ["name"] = "Void-Twisted Sporbit", ["text"] = "Binds when picked up\n\"Crush the sporbit to convert the last of its lifeforce into a Nebulous Voidcore.\"\nSell Price:" }
entries[269269] = { ["name"] = "Devouring Ritual Spire", ["text"] = "5\nDevouring Ritual Spire\nHousing Decor\nBinds to Warband\nUse: Add this Decor to your House Chest." }
entries[269316] = { ["name"] = "Bartender Bob's \"No Weapons Allowed\" Rack", ["text"] = "5\nBartender Bob's \"No Weapons Allowed\" Rack\nHousing Decor\nBinds to Warband\nUse: Add this Decor to your House Chest.\nComplete the achievement \"Highly Decorated\"\nSell Price:" }
entries[269578] = { ["name"] = "Poison Dart Frog Gland", ["text"] = "Quest Item\n\"This organ is disturbingly warm, and excretes a mucus that numbs your skin on contact.\"" }
entries[269586] = { ["name"] = "Emergency Soul Link", ["text"] = "Use: Convince a dead ally that being alive is much more fun by catalyzing your whimsy, restoring them to life with 35% health and 10% mana. This always succeeds because it's objective truth.\n\nCastable in combat. Item quality affects cast time. Cannot be used by players higher than level 90. (10 Min Cooldown)\nSell Price:" }
entries[269603] = { ["name"] = "Verdant Stalker Sludge", ["text"] = "Quest Item\nUnique (8)\n\"Positively teeming with life of all sorts.\"" }
