entries[269659] = { ["name"] = "The Sire's Palanquin", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This mount is so comfortable that you will sleep like the dead while riding it.\"\nPromotion" }
entries[269666] = { ["name"] = "Feather of Jan'alai", ["text"] = "Quest Item\n\"A small piece of the loa herself. Even a single feather emanates a slight warmth in your hand.\"" }
entries[269668] = { ["name"] = "Hungering Oblivium", ["text"] = "Quest Item\n\"An oddity of the Voidstorm. It emanates an eerie malice. Decimus requires it to be empowered with violence in order to forge the Nilhammer.\"" }
