entries[269828] = { ["name"] = "Void-Corrupted Eagle Talon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\n\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"A vile ritual can give the ritual master great power. It can also give the target of the ritual great power. This can sometimes go well or poorly for the ritual master.\"\nRitual Site:\nBroken Throne" }
entries[269829] = { ["name"] = "Void-Scarred Eaglet", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to summon this companion.\n\nRight Click to summon and dismiss your eaglet.\nRequires level 1 to 90 ( 90)" }
